float ang2 = ang_lq * M_INV_PI_2;
// ROTATION OVER TIME
ang2 += uTime*0.025;   //rotate over uTime
// FIN TYPE
float fins = 8;//3 + floor(rand_preset.z*5.95);
ang2 = cos(ang2*M_PI_2*fins) * 0.023;
ang2 *= M_PI_2;
uv2 = 0.5 + rad2*vec2(cos(ang2),sin(ang2))*(vec2(1.0)/uTexSize);
ret = texture(sampler_main, uv2).xyz;
ret *= 1.0; // a little bit of overbright
}

